{"file_text": """"Request handlers."""

from app.services import users

_MAX_PAGE_SIZE = 50
_MAX_SQLITE_INT = 2**63 - 1


def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user


def _parse_count(raw, default: str) -> int | None:
    """Parse a decimal digit string, returning None when it is invalid."""
    if raw is None:
        raw = default
    if not isinstance(raw, str) or not raw.isascii() or not raw.isdigit():
        return None
    return int(raw)


def handle_users_page(params: dict) -> tuple[int, dict]:
    page = _parse_count(params.get("page"), "1")
    page_size = _parse_count(params.get("page_size"), "10")
    if page is None or page_size is None or page < 1 or not 1 <= page_size <= _MAX_PAGE_SIZE:
        return 400, {"error": "invalid paging"}
    total = users.count_users()
    offset = (page - 1) * page_size
    rows = [] if offset > _MAX_SQLITE_INT else users.list_users(page_size, offset)
    return 200, {"users": rows, "page": page, "page_size": page_size, "total": total}", "path": "app/api/handlers.py"}

